<template><main class="auth-page"><section class="auth-panel"><div class="auth-heading"><h1>设置新密码</h1><p>首次登录需要修改初始密码后继续使用系统</p></div><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="当前密码" prop="old"><el-input v-model="form.old" type="password" show-password /></el-form-item><el-form-item label="新密码" prop="next"><el-input v-model="form.next" type="password" show-password /></el-form-item><el-form-item label="确认新密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password /></el-form-item><el-button type="primary" class="auth-submit" :loading="loading" @click="submit">确认修改</el-button></el-form></section></main></template>
<script setup>
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { useAuthStore } from '../stores/auth'
const auth = useAuthStore(); const router = useRouter(); const formRef = ref(); const loading = ref(false); const form = reactive({ old: '', next: '', confirm: '' })
const rules = { old: [{ required: true, message: '请输入当前密码' }], next: [{ required: true, min: 8, message: '至少 8 位且包含字母和数字' }], confirm: [{ validator: (_, value, callback) => value === form.next ? callback() : callback(new Error('两次密码不一致')) }] }
async function submit() { if (!(await formRef.value.validate().catch(() => false))) return; loading.value = true; try { await auth.changePassword(form.old, form.next); ElMessage.success('密码修改成功'); router.replace('/dashboard') } catch (error) { ElMessage.error(error.businessMessage) } finally { loading.value = false } }
</script>
